ALTER TABLE "formats" ADD COLUMN "family" text;--> statement-breakpoint
ALTER TABLE "formats" ADD COLUMN "leagues" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "formats" ADD COLUMN "search_terms" text DEFAULT '' NOT NULL;--> statement-breakpoint
ALTER TABLE "formats" ADD COLUMN "sort_order" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
