ALTER TABLE "rooms" ADD COLUMN "basis_preset_version" integer;--> statement-breakpoint
CREATE INDEX "rooms_basis_preset_idx" ON "rooms" ("basis_format_id","basis_preset_version");--> statement-breakpoint
--> MATCH FULL is hand-added: drizzle-kit cannot spell it, and a half-null
--> basis must never pass the FK (FMT-1).
ALTER TABLE "rooms" ADD CONSTRAINT "rooms_basis_preset_fk" FOREIGN KEY ("basis_format_id","basis_preset_version") REFERENCES "format_presets"("format_id","version") MATCH FULL;--> statement-breakpoint
ALTER TABLE "formats" ADD CONSTRAINT "formats_catalog_role_check" CHECK ("catalog_role" is null or "catalog_role" in ('standard', 'template'));--> statement-breakpoint
ALTER TABLE "formats" ADD CONSTRAINT "formats_catalog_is_publisher_owned" CHECK ("catalog_role" is null or "created_by_actor_id" is null);--> statement-breakpoint
ALTER TABLE "formats" ADD CONSTRAINT "formats_standard_ids" CHECK ("catalog_role" is distinct from 'standard' or "id" in ('policy', 'value', 'freestyle'));--> statement-breakpoint
ALTER TABLE "formats" ADD CONSTRAINT "formats_family_for_templates" CHECK (("family" is not null) = coalesce("catalog_role" = 'template', false));--> statement-breakpoint
ALTER TABLE "formats" ADD CONSTRAINT "formats_family_check" CHECK ("family" is null or "family" in ('policy', 'value', 'parli', 'other'));--> statement-breakpoint
ALTER TABLE "rooms" ADD CONSTRAINT "rooms_basis_complete" CHECK (("basis_format_id" is null) = ("basis_preset_version" is null));--> statement-breakpoint
--> Existing One-on-one presets keep ranked play (ranked admission now reads
--> eligibility); every new preset defaults to ineligible.
UPDATE "format_presets" SET "ranked_eligible" = true WHERE "format_id" = 'one-on-one';
--> statement-breakpoint
--> Publication invariant: a format the picker lists always has a current
--> preset pinned to its current revision. Deferred to commit, so a
--> publication may move the pointer and the preset in either order; fires on
--> both tables and checks old and new parents, so a preset-only supersession
--> or deletion cannot bypass it.
CREATE OR REPLACE FUNCTION formats_assert_current_preset(target text) RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp
AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "formats" f
    WHERE f."id" = target
      AND f."catalog_role" IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM "format_presets" p
        WHERE p."format_id" = f."id"
          AND p."format_version" = f."current_version"
          AND p."superseded_at" IS NULL
      )
  ) THEN
    RAISE EXCEPTION 'A catalog format needs a current preset at its current revision'
      USING ERRCODE = '23514', CONSTRAINT = 'formats_current_preset_present';
  END IF;
END
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION formats_current_preset_present() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp
AS $$
BEGIN
  IF TG_TABLE_NAME = 'formats' THEN
    PERFORM formats_assert_current_preset(NEW."id");
  ELSE
    IF TG_OP <> 'INSERT' THEN
      PERFORM formats_assert_current_preset(OLD."format_id");
    END IF;
    IF TG_OP <> 'DELETE' THEN
      PERFORM formats_assert_current_preset(NEW."format_id");
    END IF;
  END IF;
  RETURN NULL;
END
$$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "formats_current_preset_present"
  AFTER INSERT OR UPDATE ON "formats"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION formats_current_preset_present();
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "format_presets_current_preset_present"
  AFTER INSERT OR UPDATE OR DELETE ON "format_presets"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION formats_current_preset_present();
--> statement-breakpoint
